export const config = {
  runtime: 'edge',
}

const HOSTNAME_PATTERN = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/

function configuredCanvasHosts() {
  const value = globalThis.process?.env?.CANVAS_ALLOWED_HOSTS ?? ''
  return value.split(',').map((host) => host.trim()).filter(Boolean)
}

/**
 * Accept Canvas-owned hosts by default and exact, deployment-configured custom
 * domains. The header must contain only a DNS hostname, never a URL or port.
 */
export function normalizeCanvasHost(rawHost, additionalHosts = configuredCanvasHosts()) {
  const hostname = rawHost?.trim().toLowerCase()
  if (!hostname || !HOSTNAME_PATTERN.test(hostname)) return null

  const isInstructureHost = hostname === 'instructure.com' || hostname.endsWith('.instructure.com')
  const isConfiguredHost = additionalHosts.some((host) => host.trim().toLowerCase() === hostname)

  return isInstructureHost || isConfiguredHost ? hostname : null
}

export default async function handler(req) {
  const url = new URL(req.url)

  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 200,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
        'Access-Control-Allow-Headers': 'Authorization, Content-Type, X-Canvas-Host',
      },
    })
  }

  // Get the Canvas domain from header
  const rawCanvasHost = req.headers.get('x-canvas-host')
  if (!rawCanvasHost) {
    return new Response(JSON.stringify({ error: 'Missing X-Canvas-Host header' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // Validate and normalize before using user-controlled input in an outbound URL.
  const canvasHost = normalizeCanvasHost(rawCanvasHost)
  if (!canvasHost) {
    return new Response(JSON.stringify({ error: 'Invalid Canvas host' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  // Get the path after /api/canvas/
  const canvasPath = url.pathname.replace('/api/canvas/', '')
  const queryString = url.search

  // Build the Canvas API URL
  const canvasUrl = `https://${canvasHost}/api/v1/${canvasPath}${queryString}`

  try {
    const headers = {
      'Accept': 'application/json',
    }
    const authHeader = req.headers.get('authorization')
    if (authHeader) {
      headers['Authorization'] = authHeader
    }

    const canvasRes = await fetch(canvasUrl, {
      method: req.method,
      headers,
    })

    const data = await canvasRes.text()

    const responseHeaders = {
      'Content-Type': canvasRes.headers.get('content-type') || 'application/json',
      'Access-Control-Allow-Origin': '*',
    }

    // Forward Link header for pagination
    const linkHeader = canvasRes.headers.get('link')
    if (linkHeader) {
      responseHeaders['Link'] = linkHeader
    }

    return new Response(data, {
      status: canvasRes.status,
      headers: responseHeaders,
    })
  } catch {
    return new Response(JSON.stringify({ error: 'Failed to reach Canvas API' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    })
  }
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import handler, { normalizeCanvasHost } from './canvas.js'

function requestFor(host) {
  return {
    method: 'GET',
    url: 'https://checklist.example/api/canvas/courses?enrollment_state=active',
    headers: new Headers({
      'Authorization': 'Bearer test-token',
      'X-Canvas-Host': host,
    }),
  }
}

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('normalizeCanvasHost', () => {
  it('accepts Canvas-owned subdomains and normalizes case', () => {
    expect(normalizeCanvasHost('  IVC-New.Instructure.com  ', [])).toBe('ivc-new.instructure.com')
  })

  it('accepts an exact custom domain only when configured', () => {
    expect(normalizeCanvasHost('canvas.school.edu', ['canvas.school.edu'])).toBe('canvas.school.edu')
    expect(normalizeCanvasHost('canvas.school.edu', [])).toBeNull()
  })

  it.each([
    'instructure.com.attacker.test',
    'canvas-attacker.test',
    'https://school.instructure.com',
    'school.instructure.com/path',
    'school.instructure.com:443',
    'school.instructure.com@127.0.0.1',
    'canvas',
  ])('rejects unsafe host input: %s', (host) => {
    expect(normalizeCanvasHost(host, [])).toBeNull()
  })
})

describe('Canvas proxy', () => {
  it('rejects a deceptive hostname without making an outbound request', async () => {
    const fetchMock = vi.fn()
    vi.stubGlobal('fetch', fetchMock)

    const response = await handler(requestFor('instructure.com.attacker.test'))

    expect(response.status).toBe(400)
    await expect(response.json()).resolves.toEqual({ error: 'Invalid Canvas host' })
    expect(fetchMock).not.toHaveBeenCalled()
  })

  it('forwards a valid host using its normalized hostname', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response('[]', {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    }))
    vi.stubGlobal('fetch', fetchMock)

    const response = await handler(requestFor('IVC-New.Instructure.com'))

    expect(response.status).toBe(200)
    expect(fetchMock).toHaveBeenCalledWith(
      'https://ivc-new.instructure.com/api/v1/courses?enrollment_state=active',
      expect.objectContaining({ method: 'GET' }),
    )
  })
})

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { server } from '../test/mocks/server'
import { errorHandlers } from '../test/mocks/handlers'
import { fetchAssignments } from './canvas'
import { useSettingsStore } from '../store/settingsStore'

describe('fetchAssignments', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-02-01T12:00:00Z'))

    // Set up mock settings before each test
    useSettingsStore.setState({
      canvasInstances: [{
        id: 'test-instance',
        name: 'Test School',
        token: 'test-token',
        url: 'test.instructure.com',
      }],
      timeframeDays: 30,
    })
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('fetches and transforms per-course assignments', async () => {
    const assignments = await fetchAssignments()

    expect(assignments).toHaveLength(2)
    expect(assignments[0]).toMatchObject({
      id: 'test-instance:1001',
      name: 'Homework 1',
      course_name: 'Intro to Computer Science',
    })
    expect(assignments[1]).toMatchObject({
      id: 'test-instance:1002',
      name: 'Quiz 2',
      course_name: 'Calculus I',
    })
  })

  it('handles all_day_date by converting to ISO format', async () => {
    const assignments = await fetchAssignments()

    // all_day_date should be converted to ISO format with T23:59:59Z
    expect(assignments[0].due_at).toBe('2025-02-10T23:59:59Z')
  })

  it('uses start_at/end_at when all_day_date is null', async () => {
    const assignments = await fetchAssignments()

    // Should use end_at when all_day_date is null
    expect(assignments[1].due_at).toBe('2025-02-15T11:00:00Z')
  })

  it('throws error on 401 unauthorized', async () => {
    server.use(errorHandlers.unauthorized)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Invalid Canvas token')
  })

  it('throws error on server errors', async () => {
    server.use(errorHandlers.serverError)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Canvas API error: 500')
  })

  it('skips courses that return malformed assignment data', async () => {
    server.use(errorHandlers.invalidJson)

    await expect(fetchAssignments()).resolves.toEqual([])
  })
})

import { http, HttpResponse } from 'msw'

const mockCourses = [
  { id: 123456, name: 'Intro to Computer Science' },
  { id: 789012, name: 'Calculus I' },
]

const mockAssignments = new Map([
  ['123456', [{ id: 1001, name: 'Homework 1', due_at: '2025-02-10T23:59:59Z' }]],
  ['789012', [{ id: 1002, name: 'Quiz 2', due_at: '2025-02-15T11:00:00Z' }]],
])

export const handlers = [
  http.get('/api/canvas/courses', ({ request }) => {
    const url = new URL(request.url)
    const enrollmentState = url.searchParams.get('enrollment_state')

    if (enrollmentState === 'active') {
      return HttpResponse.json(mockCourses)
    }
    return HttpResponse.json([])
  }),

  http.get('/api/canvas/courses/:courseId/assignments', ({ params }) => {
    return HttpResponse.json(mockAssignments.get(String(params.courseId)) ?? [])
  }),
]

export const errorHandlers = {
  unauthorized: http.get('/api/canvas/courses', () => {
    return new HttpResponse(null, { status: 401 })
  }),

  serverError: http.get('/api/canvas/courses', () => {
    return new HttpResponse(null, { status: 500 })
  }),

  invalidJson: http.get('/api/canvas/courses/:courseId/assignments', () => {
    return new HttpResponse('not valid json', {
      headers: { 'Content-Type': 'application/json' },
    })
  }),
}
